                 (s_[2], "این گزارش پوششِ منبع است و داوریِ نهایی مقابله نشده است.", s_[1]),
                 (m[2], "این تحلیل چارچوب‌مند است و دربارهٔ اشخاص داوری نمی‌کند."),
